from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import event

router = APIRouter(prefix="/assets")

def cascade_tag_policy(session):
    for obj in session.dirty:
        if isinstance(obj, AssetTag) and "security_label" in session.is_modified(obj, include_collections=False):
            session.query(Document).filter(
                Document.workspace_id == obj.workspace_id,
                Document.tag_name == obj.tag_name
            ).update({"classification_label": obj.security_label}, synchronize_session=False)

@router.patch("/tags/{tag_id}")
async def update_asset_tag(
    tag_id: int,
    payload: TagUpdateRequest,
    db: AsyncSession = Depends(get_async_session),
    user: WorkspaceUser = Depends(get_workspace_user)
):
    tag = await db.get(AssetTag, tag_id)
    if not tag or tag.workspace_id != user.workspace_id:
        raise HTTPException(status_code=404, detail="Tag not found in user workspace")

    tag.security_label = payload.new_security_label
    await db.commit()
    return {"status": "tag_updated", "tag_id": tag_id}
